      int task1Duration = sortedTasks.get(idx);
      ArrayList<Integer> indicesWithTask1Duration = taskDurationsToIndices.get(task1Duration);
      int task1Index = indicesWithTask1Duration.remove(indicesWithTask1Duration.size() - 1);

