fun taskAssignment(k: Int, tasks: List<Int>): List<List<Int>> {
    val pairedTasks = mutableListOf<List<Int>>()
    val taskDurationsToIndices = getTaskDurationsToIndices(tasks)

    val sortedTasks = tasks.sorted()
